"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[6212],{90911(e,t,o){o.r(t),o.d(t,{assets:()=>i,contentTitle:()=>r,default:()=>d,frontMatter:()=>s,metadata:()=>h,toc:()=>l});var n=o(74848),a=o(28453);const s={lang:"en",title:"Preface: Structures Don't Need Villains",sidebar_label:"Preface",slug:"/who-collects-at-the-door/preface",description:"Imagine that one day in October 2026 you pick up your phone and see four headlines.",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},r=void 0,h={id:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/preface",title:"Preface: Structures Don't Need Villains",description:"Imagine that one day in October 2026 you pick up your phone and see four headlines.",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322/preface.md",sourceDirName:"\u8cc7\u672c\u904a\u6232\u73a9\u4ec0\u9ebc\uff08\u5be6\u4f8b\u6a94\u6848\uff1a\u904a\u6232\u696d\uff09/\u8ab0\u5728\u9580\u53e3\u6536\u9322",slug:"/who-collects-at-the-door/preface",permalink:"/en/docs/who-collects-at-the-door/preface",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{lang:"en",title:"Preface: Structures Don't Need Villains",sidebar_label:"Preface",slug:"/who-collects-at-the-door/preface",description:"Imagine that one day in October 2026 you pick up your phone and see four headlines.",keywords:["Who's Collecting at the Door","financialization","Nebula Walker"]},sidebar:"docs",previous:{title:"Book Info",permalink:"/en/docs/who-collects-at-the-door"},next:{title:"1. What Financialization Cuts Is Not R&D",permalink:"/en/docs/who-collects-at-the-door/ch01"}},i={},l=[{value:"1. Four Headlines",id:"1-four-headlines",level:2},{value:"2. Seeing How Money Flows",id:"2-seeing-how-money-flows",level:2},{value:"3. Where I Stand",id:"3-where-i-stand",level:2},{value:"4. What This Book Is Not",id:"4-what-this-book-is-not",level:2},{value:"5. How to Read This Book",id:"5-how-to-read-this-book",level:2}];function c(e){const t={a:"a",h1:"h1",h2:"h2",hr:"hr",p:"p",table:"table",th:"th",thead:"thead",tr:"tr",...(0,a.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Who's Collecting at the Door"})," \uff5c ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/full",children:"\ud83d\udcd6 Full Edition"})]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h1,{id:"preface-structures-dont-need-villains",children:"Preface: Structures Don't Need Villains"}),"\n",(0,n.jsx)(t.h2,{id:"1-four-headlines",children:"1. Four Headlines"}),"\n",(0,n.jsx)(t.p,{children:"Imagine that one day in October 2026 you pick up your phone and see four headlines."}),"\n",(0,n.jsx)(t.p,{children:"One says AI will replace a large share of white-collar work, and anyone who doesn't learn it will be left behind. One says a long-established restaurant group and the partner it has worked with for more than fifty years have parted ways amicably, each taking what it needs. One says the myth of young people's micro-entrepreneurship has collapsed, and going back to a salaried job is the safe choice. And one is about an entertainer who was told by a show's host that she got the short end of things because she didn't have enough backbone."}),"\n",(0,n.jsx)(t.p,{children:"Four headlines, four explanations: technological progress, an amicable split, naive founders, a flaw in someone's character. Each explanation is partly true. But they have one thing in common: none of them tells you where the money went."}),"\n",(0,n.jsx)(t.p,{children:"Four of this book's nine chapters start from these four headlines (see Chapters 1, 2, 7 and 9)."}),"\n",(0,n.jsx)(t.h2,{id:"2-seeing-how-money-flows",children:"2. Seeing How Money Flows"}),"\n",(0,n.jsx)(t.p,{children:"I have come to believe that life is, to a large degree, a game of strategy. The game itself is not what should frighten you. What should frighten you is not knowing who else is at the table, who wrote the rules, and who takes a cut of every hand."}),"\n",(0,n.jsx)(t.p,{children:"And the story follows the money. The side collecting the money always has a reason to tell a pleasant story: transformation, upgrading, professionalization, win-win. The side paying hears a different story most often: you didn't try hard enough, you aren't tough enough, you can't keep up with the times. Nobody necessarily invents either story on purpose. Wherever the money flows, someone there is willing to tell the story a little more smoothly."}),"\n",(0,n.jsx)(t.p,{children:"So this book uses a single method. Each time you hear an explanation, don't ask first whether it is right. Ask: where is the money flowing from, and to where? Whichever exit you take, who is standing at the door collecting?"}),"\n",(0,n.jsxs)(t.p,{children:["That doesn't mean every explanation is false. AI really is useful, just as computers and the internet really were useful. The technology is real and the story is real; they happen at the same time, but they are not the same thing (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch01",children:"Chapter 1"}),"). Seeing how money flows is how you tell the two apart."]}),"\n",(0,n.jsx)(t.h2,{id:"3-where-i-stand",children:"3. Where I Stand"}),"\n",(0,n.jsx)(t.p,{children:"I have worked in R&D, written embedded systems, solved customers' problems in the field, and later worked in corporate strategy. Some of the companies I worked for were expanding, some were buying up others, and some were slowly shrinking. As a child I grew up next to my family's small trading business; I watched it expand, and I watched it fall into infighting because it could not collect what it was owed. Many of the examples in this book were seen from those positions."}),"\n",(0,n.jsxs)(t.p,{children:["But I have to be clear about something. I spent most of my career in companies that were growing, and I ran into real backstabbing only once. Part Two will argue that where a person stands decides what they see (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch04",children:"Chapter 4"}),"). I am a position too, a single sample."]}),"\n",(0,n.jsx)(t.p,{children:"So you need not take everything I saw on trust. A better way to read this book is to take its questions and check them against what you have seen yourself."}),"\n",(0,n.jsx)(t.h2,{id:"4-what-this-book-is-not",children:"4. What This Book Is Not"}),"\n",(0,n.jsx)(t.p,{children:"It does not teach you how to win. There are already plenty of books and courses that do, and most of them assume you are standing on a fair stage. This book is about the places where that assumption fails."}),"\n",(0,n.jsxs)(t.p,{children:["It is not against technology, and it is not against making money. Someone else doing well has not necessarily taken anything from you; the world is not zero-sum everywhere (see ",(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch04",children:"Chapter 4"}),")."]}),"\n",(0,n.jsx)(t.p,{children:"Nor does it hunt for villains. This is the point I most want to make up front. Very few of the companies, platforms, hosts and HR departments in this book set out to do harm. Each of their steps is a rational response to the step before; but once the loop is complete, the result lands on someone who did nothing wrong. Structures don't need villains. Precisely because they don't need villains, they are hard to see, and easy to describe as your own problem."}),"\n",(0,n.jsx)(t.h2,{id:"5-how-to-read-this-book",children:"5. How to Read This Book"}),"\n",(0,n.jsx)(t.p,{children:"The book has three parts, and each asks one question."}),"\n",(0,n.jsx)(t.p,{children:"Part One (Chapters 1 to 3) asks: what shape is this structure? From an R&D department quietly replaced inside a company, to chicken that no longer tastes like chicken, to the entry fee charged at every exit."}),"\n",(0,n.jsx)(t.p,{children:"Part Two (Chapters 4 to 6) asks: why can you see it when others can't? And the reverse: why can others see it when you can't?"}),"\n",(0,n.jsx)(t.p,{children:"Part Three (Chapters 7 to 9) asks: once the cost of a structure lands on one person, how does it get described as that person's flaw?"}),"\n",(0,n.jsx)(t.p,{children:"The conclusion tries to answer: knowing all this, what can you do?"}),"\n",(0,n.jsx)(t.p,{children:"Almost every example in the book carries a date, most of them in 2026. This is deliberate. Ten years from now, the companies in this book may have gone public or been sold, the shops may have closed, the platforms may have been renamed, and AI may have been replaced by the next round's name. By then these examples will have become a record: the world as one person saw it in 2026."}),"\n",(0,n.jsx)(t.p,{children:"What you should take away is not the examples but the method. Many chapters end with a few questions that can be asked without any inside information, and that will not stop working because a platform or a technology changes its name. It doesn't matter if you don't know the people in this book or never heard of the controversies. The examples are a record; the method is a tool. Records age; tools don't."}),"\n",(0,n.jsx)(t.p,{children:'Each chapter can be read on its own; chapters point to one another with "(see Chapter X)". Sources and my other articles are cited by numbered notes; in this web edition they appear at the end of each chapter.'}),"\n",(0,n.jsx)(t.p,{children:"The title comes from a question in Chapter 9: whichever exit you take, who is standing at the door collecting? The subtitle is the conclusion's answer. The nine chapters in between are the road from the question to the answer."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.table,{children:(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{style:{textAlign:"left"}}),(0,n.jsx)(t.th,{style:{textAlign:"center"},children:(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door",children:"\ud83d\udcd6 Back to Contents"})}),(0,n.jsx)(t.th,{style:{textAlign:"right"},children:(0,n.jsx)(t.a,{href:"/en/docs/who-collects-at-the-door/ch01",children:'Chapter 1: What Financialization Cuts Is Not R&D, but the Word "No" \u2192'})})]})})})]})}function d(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(c,{...e})}):c(e)}},28453(e,t,o){o.d(t,{R:()=>r,x:()=>h});var n=o(96540);const a={},s=n.createContext(a);function r(e){const t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function h(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);